"2015": {"tmdb_id": 2015, "imdb_id": "tt0817225", "title": "Secret Sunshine", "original_title": "밀양", "year": 2007, "directors": ["Lee Chang-dong"], "countries": ["KR"], "runtime": 143, "cast": ["Jeon Do-yeon", "Song Kang-ho", "Jo Young-jin", "Seon Jeong-yeop", "Kim Young-jae", "Park Myung-shin"], "overview": "Shin-ae moves to her recently late husband’s hometown. Despite her efforts to settle in this unfamiliar and too-normal place, she finds that she can’t fit in. After a sudden tragedy, Shin-ae turns to Christianity to relieve her pain, but when even this is not permitted, she wages a war against God.", "poster": "https://image.tmdb.org/t/p/w342/vee1jyUrqUEmi5ZStWI1JJzLQJH.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/bJd4hoeLCQIqqZnyQ9W1Bh5dIY7.jpg"},
"2039": {"tmdb_id": 2039, "imdb_id": "tt0093565", "title": "Moonstruck", "original_title": "Moonstruck", "year": 1987, "directors": ["Norman Jewison"], "countries": ["US"], "runtime": 102, "cast": ["Cher", "Nicolas Cage", "Vincent Gardenia", "Olympia Dukakis", "Danny Aiello", "Julie Bovasso"], "overview": "37-year-old Italian-American widow Loretta Castorini believes she is unlucky in love, and so accepts a marriage proposal from her boyfriend Johnny, even though she doesn't love him. When she meets his estranged younger brother Ronny, an emotional and passionate man, she finds herself drawn to him. She tries to resist, but Ronny, who blames his brother for the loss of his hand, has no scruples about aggressively pursuing her while Johnny is out of the country. As Loretta falls for Ronny, she learns that she's not the only one in her family with a secret romance.", "poster": "https://image.tmdb.org/t/p/w342/2mnVWpvsHEHHnfvLn1NXYVvBGl5.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/5RQ5SIcrtKeUYeYeJLRTljR8LcN.jpg"},
