"11386": {"tmdb_id": 11386, "imdb_id": "tt0104036", "title": "The Crying Game", "original_title": "The Crying Game", "year": 1992, "directors": ["Neil Jordan"], "countries": ["GB", "JP"], "runtime": 112, "cast": ["Stephen Rea", "Miranda Richardson", "Jaye Davidson", "Forest Whitaker", "Adrian Dunbar", "Breffni McKenna"], "overview": "Irish Republican Army member Fergus forms an unexpected bond with Jody, a kidnapped British soldier in his custody, despite the warnings of fellow IRA members Jude and Maguire. Jody makes Fergus promise he'll visit his girlfriend, Dil, in London, and when Fergus flees to the city, he seeks her out. Hounded by his former IRA colleagues, he finds himself increasingly drawn to the enigmatic, and surprising, Dil.", "poster": "https://image.tmdb.org/t/p/w342/9BXGoat9TYgdDqGk2WJmaX9dVoe.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/k4ZrvqTWADP1nzgXNSKDNk4xOEB.jpg"},
"11387": {"tmdb_id": 11387, "imdb_id": "tt0059399", "title": "Lord Jim", "original_title": "Lord Jim", "year": 1965, "directors": ["Richard Brooks"], "countries": ["GB", "US"], "runtime": 154, "cast": ["Peter O'Toole", "James Mason", "Curd Jürgens", "Eli Wallach", "Jack Hawkins", "Paul Lukas"], "overview": "After being discredited as a coward, a 19th century seaman lives for only one purpose: to redeem himself.  Preserved by the Academy Film Archive in partnership with Sony Pictures Entertainment in 2000.", "poster": "https://image.tmdb.org/t/p/w342/hgoxcPLJYYqDIlFDl7pnndcm9MT.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/ePEMEklx5d5ItZ1Cp5CDqJiP3Ms.jpg"},
"11416": {"tmdb_id": 11416, "imdb_id": "tt0091530", "title": "The Mission", "original_title": "The Mission", "year": 1986, "directors": ["Roland Joffé"], "countries": ["GB", "FR", "US"], "runtime": 125, "cast": ["Robert De Niro", "Jeremy Irons", "Ray McAnally", "Aidan Quinn", "Liam Neeson", "Cherie Lunghi"], "overview": "Når en spansk jesuitt drar ut i den søramerikanske villmarken for å bygge et oppdrag i håp om å omvende indianerne i regionen, blir en slavejeger omvendt og slutter seg til oppdraget hans. Når Spania selger kolonien til Portugal, blir de tvunget til å forsvare alt de har bygget mot de portugisiske aggressorene.", "poster": "https://image.tmdb.org/t/p/w342/6K9cG6LOOtySZF4D4xBu1MApC1N.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/izgDdMvuRvTtA2azhKwPvfITZU1.jpg"},
