"16993": {"tmdb_id": 16993, "imdb_id": "tt0068575", "title": "Fat City", "original_title": "Fat City", "year": 1972, "directors": ["John Huston"], "countries": ["US"], "runtime": 97, "cast": ["Stacy Keach", "Jeff Bridges", "Susan Tyrrell", "Candy Clark", "Nicholas Colasanto", "Art Aragon"], "overview": "The story of two men, a veteran boxer who is down and out, and a young man who is just starting his life and boxing career. Their fighting careers cross paths as their lives and fortunes head in opposite directions.", "poster": "https://image.tmdb.org/t/p/w342/7ag7BOMnAuDKwNyI0wc8jTeimRb.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/fHKyWtxGIDQ21JcL7Le6rmX36Q1.jpg"},
