"17685": {"tmdb_id": 17685, "imdb_id": "tt0060908", "title": "King of Hearts", "original_title": "Le Roi de cœur", "year": 1966, "directors": ["Philippe de Broca"], "countries": ["FR", "IT"], "runtime": 102, "cast": ["Alan Bates", "Geneviève Bujold", "Pierre Brasseur", "Michel Serrault", "Jean-Claude Brialy", "Adolfo Celi"], "overview": "An ornithologist mistaken for an explosives expert is sent alone into a small French town during WWI to investigate a garbled report from the resistance about a bomb which the departing Germans have set to blow up a weapons cache.", "poster": "https://image.tmdb.org/t/p/w342/7RekNiu247cWDPfSqMyX77Yoez4.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/wjocv4un0nuaDhwfQg0OCDtwWK1.jpg"},
"17814": {"tmdb_id": 17814, "imdb_id": "tt0074156", "title": "Assault on Precinct 13", "original_title": "Assault on Precinct 13", "year": 1976, "directors": ["John Carpenter"], "countries": ["US"], "runtime": 91, "cast": ["Austin Stoker", "Darwin Joston", "Laurie Zimmer", "Martin West", "Tony Burton", "Charles Cyphers"], "overview": "A highway patrol officer, two criminals, and a station secretary form an unlikely alliance to defend a defunct Los Angeles precinct against a siege by a bloodthirsty street gang.", "poster": "https://image.tmdb.org/t/p/w342/RtGDEmXbSxE8NThCCY1SXFXLLw.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/dm1bqDSw3MJTjYCeuNUv122BXFp.jpg"},
