"18900": {"tmdb_id": 18900, "imdb_id": "tt0061809", "title": "In Cold Blood", "original_title": "In Cold Blood", "year": 1967, "directors": ["Richard Brooks"], "countries": ["US"], "runtime": 134, "cast": ["Robert Blake", "Scott Wilson", "John Forsythe", "Paul Stewart", "Gerald S. O'Loughlin", "Jeff Corey"], "overview": "After a botched robbery results in the brutal murder of a rural family, two drifters elude police, in the end coming to terms with their own mortality and the repercussions of their vile atrocity.", "poster": "https://image.tmdb.org/t/p/w342/sPEvsif5Y70mfVvtU39iOyrVJdF.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/gQYsE1Zu89fbi3yUL4bubxoRjbh.jpg"},
