"19119": {"tmdb_id": 19119, "imdb_id": "tt0042788", "title": "Night and the City", "original_title": "Night and the City", "year": 1950, "directors": ["Jules Dassin"], "countries": ["GB"], "runtime": 95, "cast": ["Richard Widmark", "Francis L. Sullivan", "Gene Tierney", "Googie Withers", "Stanislaus Zbyszko", "Herbert Lom"], "overview": "Londoner Harry Fabian is a second-rate con man looking for an angle. After years of putting up with Harry's schemes, his girlfriend, Mary, becomes fed up when he taps her for yet another loan.", "poster": "https://image.tmdb.org/t/p/w342/2NBmzm8z5fd283eWeECkPrkwta8.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/15mrnCjsVRJafPhdsRKvmbhu3S0.jpg"},
"19120": {"tmdb_id": 19120, "imdb_id": "tt0059229", "title": "Juliet of the Spirits", "original_title": "Giulietta degli spiriti", "year": 1965, "directors": ["Federico Fellini"], "countries": ["IT", "FR"], "runtime": 148, "cast": ["Giulietta Masina", "Sandra Milo", "Mario Pisu", "Valentina Cortese", "Valeska Gert", "José Luis de Vilallonga"], "overview": "Middle-aged Giulietta grows suspicious of her husband, Giorgio, when his behavior grows increasingly questionable. One night when Giorgio initiates a seance amongst his friends, Giulietta gets in touch with spirits and learns more about herself and her painful past. Slightly skeptical, but intrigued, she visits a mystic who gives her more information -- and nudges her toward the realization that her husband is indeed a philanderer.", "poster": "https://image.tmdb.org/t/p/w342/NbN10moPWQiiIKDJsC7A3j4Mcy.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/9VeXz4mj4QaOfTNSLy0owJHkWEo.jpg"},
"19136": {"tmdb_id": 19136, "imdb_id": "tt0033704", "title": "Hellzapoppin'", "original_title": "Hellzapoppin'", "year": 1941, "directors": ["H. C. Potter"], "countries": ["US"], "runtime": 84, "cast": ["Ole Olsen", "Chic Johnson", "Martha Raye", "Hugh Herbert", "Jane Frazee", "Robert Paige"], "overview": "Olsen and Johnson, a pair of stage comedians, try to turn their play into a movie and bring together a young couple in love, while breaking the fourth wall every step of the way.", "poster": "https://image.tmdb.org/t/p/w342/O5Ta3URiRglqt1fPi2APCvnb8x.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/jEHDsO0Wo1WThOrYM58kPAopbtM.jpg"},
"19155": {"tmdb_id": 19155, "imdb_id": "tt0110882", "title": "Before the Rain", "original_title": "Пред дождот", "year": 1994, "directors": ["Milcho Manchevski"], "countries": ["GB", "MK", "FR"], "runtime": 113, "cast": ["Katrin Cartlidge", "Rade Šerbedžija", "Grégoire Colin", "Labina Mitevska", "Phyllida Law", "Silvija Stojanovska"], "overview": "The circularity of violence seen in a story that circles on itself. In Macedonia, during the war in Bosnia, Christians hunt an ethnic Albanian girl who may have murdered one of their own. A young monk who's taken a vow of silence offers her protection. In London, a photographic editor who's pregnant needs to talk it out with her estranged husband and chooses a toney restaurant.", "poster": "https://image.tmdb.org/t/p/w342/e8DEVsL3tm0llRESDJfkRRktino.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/gUNK128qFaejz31jaQzkRmlcox9.jpg"},
