"19204": {"tmdb_id": 19204, "imdb_id": "tt0082307", "title": "The Beyond", "original_title": "...E tu vivrai nel terrore! L'aldilà", "year": 1981, "directors": ["Lucio Fulci"], "countries": ["IT"], "runtime": 88, "cast": ["Catriona MacColl", "David Warbeck", "Cinzia Monreale", "Antoine Saint-John", "Veronica Lazăr", "Larry Ray"], "overview": "New Yorker Liza Merril inherits an old hotel in Louisiana and invests her savings to reopen the place, unaware that the hotel houses the body of a dead painter murdered decades earlier, and that the location is about to become a gateway to Hell.", "poster": "https://image.tmdb.org/t/p/w342/kMSZHq9VYQV1FCbM8nz2zrZShzx.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/ysCpbgA1zxOmkb1IWKzwhTxDxk3.jpg"},
