"20372": {"tmdb_id": 20372, "imdb_id": "tt0050762", "title": "Nine Lives", "original_title": "Ni liv", "year": 1957, "directors": ["Arne Skouen"], "countries": ["NO"], "runtime": 96, "cast": ["Jack Fjeldstad", "Henny Moan", "Alf Malland", "Joachim Holst-Jensen", "Lydia Opøien", "Edvard Drabløs"], "overview": "Den 30. mars 1943 blir mannskapet på skuta Brattholm angitt og fanget i et dødelig nazistisk bakholdsangrep. Bare Jan Baalsrud unnslipper, og en eventyrlig flukt gjennom snølandskapet begynner.", "poster": "https://image.tmdb.org/t/p/w342/vzM9JWevYCMfFiibaO8z3riTyTK.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/4Ta5j0ii9mOkhR4fLQky0JurRG9.jpg"},
"20379": {"tmdb_id": 20379, "imdb_id": "tt0060472", "title": "Grand Prix", "original_title": "Grand Prix", "year": 1966, "directors": ["John Frankenheimer"], "countries": ["US", "FR", "GB", "NL", "IT", "BE", "MC"], "runtime": 176, "cast": ["James Garner", "Eva Marie Saint", "Yves Montand", "Toshirō Mifune", "Brian Bedford", "Jessica Walter"], "overview": "The most daring drivers in the world have gathered to compete for the 1966 Formula One championship. After a spectacular wreck in the first of a series of races, American wheelman Pete Aron is dropped by his sponsor. Refusing to quit, he joins a Japanese racing team. While juggling his career with a torrid love affair involving an ex-teammate's wife, Pete must also contend with Jean-Pierre Sarti, a French contestant who has previously won two world titles.", "poster": "https://image.tmdb.org/t/p/w342/yEXrf09o8wVRFSptYFr6VcqLjPr.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/96etD6qTLBfoGYZsLb9AAcSETjE.jpg"},
"20423": {"tmdb_id": 20423, "imdb_id": "tt0097372", "title": "For All Mankind", "original_title": "For All Mankind", "year": 1989, "directors": ["Al Reinert"], "countries": ["US"], "runtime": 80, "cast": ["Jim Lovell", "Russell Schweickart", "Eugene Cernan", "Michael Collins", "Charles Conrad", "Richard Gordon"], "overview": "A testament to NASA's Apollo program of the 1960s and '70s. Composed of actual NASA footage of the missions and astronaut interviews, the documentary offers the viewpoint of the individuals who braved the remarkable journey to the moon and back.", "poster": "https://image.tmdb.org/t/p/w342/7k8ylisWiEGxdRSlAf6v4PWiAjH.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/jQzQm6YPBab5ucysHaGnGzfXKCh.jpg"},
