"20532": {"tmdb_id": 20532, "imdb_id": "tt0047445", "title": "Sansho the Bailiff", "original_title": "山椒大夫", "year": 1954, "directors": ["Kenji Mizoguchi"], "countries": ["JP"], "runtime": 124, "cast": ["Kinuyo Tanaka", "Yoshiaki Hanayagi", "Kyōko Kagawa", "Eitarō Shindō", "Ichirō Sugai", "Bontarō Miake"], "overview": "In 11th-century feudal Japan, following the exile of an idealistic governor, his wife and children are separated by slave traders; the children, Zushio and Anju, are sold into brutal servitude under the cruel bailiff Sansho.", "poster": "https://image.tmdb.org/t/p/w342/cOBsWxFtEoqXIPx4JZP5E7g1WEo.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/wJfbBUiJH8C9PTAunn11Ms4KN8h.jpg"},
"20537": {"tmdb_id": 20537, "imdb_id": "tt0090798", "title": "Caravaggio", "original_title": "Caravaggio", "year": 1986, "directors": ["Derek Jarman"], "countries": ["GB"], "runtime": 93, "cast": ["Nigel Terry", "Sean Bean", "Garry Cooper", "Dexter Fletcher", "Spencer Leigh", "Tilda Swinton"], "overview": "A retelling of the life of the celebrated 17th-century Baroque painter Michelangelo Merisi da Caravaggio through his brilliant, nearly blasphemous paintings and his flirtations with the underworld.", "poster": "https://image.tmdb.org/t/p/w342/4TsayIEhoId7iahurgpKSNdSdEo.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/6srA1KSWjnysZivKIFZmROTzZuI.jpg"},
