"22624": {"tmdb_id": 22624, "imdb_id": "tt0365659", "title": "Raining Cats and Frogs", "original_title": "La Prophétie des grenouilles", "year": 2003, "directors": ["Jacques-Rémy Girerd"], "countries": ["FR"], "runtime": 90, "cast": ["Coline Girerd", "Michel Piccoli", "Kevin Hervé", "Laurentine Milebo", "Manuela Gourary", "Luis Rego"], "overview": "It's a catastrophe! A flood has hit our planet and an unusual group of people are all that remains. Led by Ferdinand, a modern day Noah, this little group have managed to defy the furiously raging elements. People and animals alike are dragged through this incredible whirlpool of an adventure.", "poster": "https://image.tmdb.org/t/p/w342/k6E3mk4NChtf38uMYsc0cvAe5IA.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/cneLWk1D9JaclanotEOyapS0IMu.jpg"},
"22638": {"tmdb_id": 22638, "imdb_id": "tt0036910", "title": "Henry V", "original_title": "The Chronicle History of King Henry the Fifth with His Battell Fought at Agincourt in France", "year": 1944, "directors": ["Laurence Olivier"], "countries": ["GB"], "runtime": 137, "cast": ["Laurence Olivier", "Renée Asherson", "Ralph Truman", "Ernest Thesiger", "Frederick Cooper", "Robert Helpmann"], "overview": "In 1415, in the midst of the Hundred Years' War, the young King Henry V of England embarks on the conquest of France.", "poster": "https://image.tmdb.org/t/p/w342/eAisr20DvaKJeHvjDN0oHSx0l7u.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/zNca9BKPRMC1WtQYVJ619bqdaOZ.jpg"},
