"24014": {"tmdb_id": 24014, "imdb_id": "tt0054022", "title": "Let's Make Love", "original_title": "Let's Make Love", "year": 1960, "directors": ["George Cukor"], "countries": ["US"], "runtime": 119, "cast": ["Marilyn Monroe", "Yves Montand", "Tony Randall", "Frankie Vaughan", "Wilfrid Hyde-White", "David Burns"], "overview": "When billionaire Jean-Marc Clement learns that he is to be satirized in an off-Broadway revue, he passes himself off as an actor playing him in order to get closer to the beautiful star of the show, Amanda Dell.", "poster": "https://image.tmdb.org/t/p/w342/yzBniSVhbXrGTRmyAH0k276NFzJ.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/gDVa3JFURhhcnic6fIhk3EPmbd0.jpg"},
