"27145": {"tmdb_id": 27145, "imdb_id": "tt0080728", "title": "The Aviator's Wife", "original_title": "La Femme de l'aviateur", "year": 1981, "directors": ["Éric Rohmer"], "countries": ["FR"], "runtime": 106, "cast": ["Philippe Marlaud", "Marie Rivière", "Anne-Laure Meury", "Mathieu Carrière", "Philippe Caroit", "Coralie Clément"], "overview": "A student is devastated when he finds that his girlfriend is cheating on him. In order to find out why she did it, he decides to spy on her and her airline pilot lover. Then he sees the pilot with a blonde woman and he begins to follow them…", "poster": "https://image.tmdb.org/t/p/w342/xgXj1Fcgq1nHjhj9i7BiqvZarn5.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/lkS9SAwibcNK3CUYmtVk1cuOsg0.jpg"},
"27197": {"tmdb_id": 27197, "imdb_id": "tt0057710", "title": "An Actor's Revenge", "original_title": "雪之丞変化", "year": 1963, "directors": ["Kon Ichikawa"], "countries": ["JP"], "runtime": 114, "cast": ["Kazuo Hasegawa", "Fujiko Yamamoto", "Ayako Wakao", "Eiji Funakoshi", "Naritoshi Hayashi", "Eijirō Yanagi"], "overview": "In Edo Japan, a kabuki actor seeks revenge against the three men who drove his parents to their deaths years ago.", "poster": "https://image.tmdb.org/t/p/w342/cNjcjBVbXoUQGsJqCkOJvog88kD.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/sd7UGHu2DasJz1mKVI0YTpQK1qo.jpg"},
"27223": {"tmdb_id": 27223, "imdb_id": "tt0089504", "title": "Lost in America", "original_title": "Lost in America", "year": 1985, "directors": ["Albert Brooks"], "countries": ["US"], "runtime": 91, "cast": ["Albert Brooks", "Julie Hagerty", "Michael Greene", "Garry Marshall", "Maggie Roswell", "Tom Tarpey"], "overview": "David and Linda Howard are successful yuppies from LA. When he gets a job disappointment, David convinces Linda that they should quit their jobs, liquidate their assets, and emulate the movie Easy Rider, spending the rest of their lives traveling around America...in a Winnebago.", "poster": "https://image.tmdb.org/t/p/w342/j7QiwUekGiYOmjKratNORIr35zg.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/7XpgGenPC31U3nsqIQPJCr8OdhY.jpg"},
