"28297": {"tmdb_id": 28297, "imdb_id": "tt0039224", "title": "Brute Force", "original_title": "Brute Force", "year": 1947, "directors": ["Jules Dassin"], "countries": ["US"], "runtime": 98, "cast": ["Burt Lancaster", "Hume Cronyn", "Charles Bickford", "Yvonne De Carlo", "Ann Blyth", "Ella Raines"], "overview": "Timeworn Joe Collins and his fellow inmates live under the heavy thumb of the sadistic, power-tripping guard Captain Munsey. Only Collins' dreams of escape keep him going, but how can he possibly bust out of Munsey's chains?", "poster": "https://image.tmdb.org/t/p/w342/xgmmXFbioGOXZTou2FS44yKa54r.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/aJcr2XzbFt2jqKtCnlw9Po1ZA2f.jpg"},
