"28333": {"tmdb_id": 28333, "imdb_id": "tt0055069", "title": "The Ladies Man", "original_title": "The Ladies Man", "year": 1961, "directors": ["Jerry Lewis"], "countries": ["US"], "runtime": 95, "cast": ["Jerry Lewis", "Helen Traubel", "Pat Stanley", "Kathleen Freeman", "George Raft", "Harry James"], "overview": "After his girl leaves him for someone else, Herbert gets really depressed and starts searching for a job. He finally finds one in a big house which is inhabited by many, many women. Can he live in the same home with all these females?", "poster": "https://image.tmdb.org/t/p/w342/c15TotHYrXPZSzjZCBfbup3fz4V.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/vH5yM2yod8DZqCk713zyWQWcKjc.jpg"},
