"1129188": {"tmdb_id": 1129188, "imdb_id": "tt27803347", "title": "The Optimist", "original_title": "The Optimist", "year": 2026, "directors": ["Finn Taylor"], "countries": ["CZ", "US"], "runtime": 102, "cast": ["Stephen Lang", "Elsie Fisher", "Luke David Blumm", "Robin Weigert", "Leah Pipes", "Ben Geurens"], "overview": "Herbert Heller keeps his experience as a teenage boy surviving in Auschwitz hidden from his family. Until he meets Abby, a young teenager whose own brush with pain and death inspires him to open up as well, leading the two of them to exchange their stories as a meaningful and healing friendship is born.", "poster": "https://image.tmdb.org/t/p/w342/kQvgYd8GaYkoovQZmE8IkbAMg2d.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/d162vjYEHGEGw2XqxH487bnEkfG.jpg"},
"1130948": {"tmdb_id": 1130948, "imdb_id": "tt27844906", "title": "Rosebush Pruning", "original_title": "Rosebush Pruning", "year": 2026, "directors": ["Karim Aïnouz"], "countries": ["DE", "IT", "GB", "ES", "CA", "BR", "FR"], "runtime": 95, "cast": ["Callum Turner", "Jamie Bell", "Riley Keough", "Elle Fanning", "Lukas Gage", "Tracy Letts"], "overview": "When an American heir living in a luxurious Spanish villa decides to move in with his girlfriend, his departure triggers a family collapse as his brother uncovers the truth behind their mother's tragic death.", "poster": "https://image.tmdb.org/t/p/w342/rsHEVjzxU8cxz1sm3vboj99daNv.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/vcZ3UUVmFNk90DBSrTBlTKCdbbE.jpg"},
