"1546852": {"tmdb_id": 1546852, "imdb_id": "tt38343530", "title": "A Goodnight Kiss", "original_title": "Irena", "year": 2025, "directors": ["Giedrė Žickytė"], "countries": ["LT", "EE", "BG"], "runtime": 87, "cast": [], "overview": "A touching tribute to the distinguished Lithuanian cultural figure Irena Veisaitė. Having survived the Holocaust and lost her loved ones, but refusing to give in to hatred, she chose forgiveness over revenge, dialogue over silence, and love over hatred, becoming an inspiration to many.", "poster": "https://image.tmdb.org/t/p/w342/2vVJujsQHDnvY0uOrfSiDzhxRdi.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/rlvfeLeAHLfkjx67teByVmT0uCk.jpg"},
